/* Neemari rotating showcase. GSAP + Draggable when present; native fallback included. */
(() => {
  'use strict';
  const root = document.querySelector('#neemari-showcase');
  if (!root) return;
  const find = selector => root.querySelector(selector);
  const all = selector => [...root.querySelectorAll(selector)];
  const media = matchMedia('(prefers-reduced-motion: reduce)');
  const finePointer = matchMedia('(hover: hover) and (pointer: fine)');
  const entries = [
    {key:'leaves',title:'Dried Neem<br><em>Leaves.</em>',plain:'Dried neem leaves',badge:'Leaf material · pilot product',description:'The leaf, before the grind. Selected and shade-dried at Barefoot College, then hand sorted for buyer evaluation.',points:['Shade-dried','Hand sorted','Batch identified'],price:'₹35 / kg',terms:'Indicative for 100 kg+ · cost & stock approval apply',image:'assets/sample-packs.webp',alt:'Actual Neemari dried neem leaf sample pouches',caption:'PROJECT SAMPLE PACKS',cta:'Enquire about leaves'},
    {key:'powder',title:'Neem Leaf<br><em>Powder.</em>',plain:'Neem leaf powder',badge:'Pulverized & sieved · pilot product',description:'Locally handled leaves, transformed into powder by the women at our processing unit. Explore screen options and agree your sample.',points:['Shade-dried input','35 / 70 mesh options','Sample-led specification'],price:'₹249 / kg',terms:'Indicative 5 kg tier · other catalogue tiers available',image:'assets/powder.webp',alt:'Actual Neemari pilot neem leaf powder sample on a plate',caption:'ACTUAL PILOT POWDER SAMPLE',cta:'Build a powder enquiry'},
    {key:'saplings',title:'Neem<br><em>Saplings.</em>',plain:'Neem saplings',badge:'Custom enquiry · stock to confirm',description:'Plan a nursery enquiry around your quantity, location and planting window. Nursery stock and seasonal readiness need confirmation.',points:['Quantity on request','Seasonal readiness','Nursery stock to confirm'],price:'Price on request',terms:'Illustration · no current nursery stock is asserted',image:'assets/sapling.svg',alt:'Illustration of a neem sapling in a nursery pot; not a stock photograph',caption:'BOTANICAL ILLUSTRATION',cta:'Enquire about saplings'},
    {key:'seeds',title:'De-pulped<br><em>Neem Seeds.</em>',plain:'De-pulped neem seeds',badge:'Seasonal enquiry · stock to confirm',description:'A seasonal raw-material route. Discuss de-pulping, dryness, purity and testing requirements ahead of the collection season.',points:['Seasonal supply route','De-pulped specification','100 kg catalogue MOQ'],price:'₹45 / kg',terms:'Indicative · season, quality, yield & stock apply',image:'assets/seeds.svg',alt:'Illustration of neem seeds; not a stock photograph',caption:'BOTANICAL ILLUSTRATION',cta:'Discuss seasonal seeds'},
    {key:'manure',title:'Neem Manure<br><em>& Cake.</em>',plain:'Neem manure / cake',badge:'Future range · development enquiry',description:'A future conversation about neem by-products. Plant-based compost is proposed; cake production and a commercial formulation are not yet established.',points:['Proposed range','Specification to develop','Availability unconfirmed'],price:'Under development',terms:'Illustration · no tested formulation or stock available',image:'assets/manure.svg',alt:'Illustration of a sack for a proposed neem manure or cake range, not an available product',caption:'CONCEPT ILLUSTRATION',cta:'Discuss future requirements'}
  ];
  const rotor=find('.dial-rotor'),surface=find('.dial-surface'),art=find('.showcase-art'),copy=find('.showcase-copy'),markers=all('.dial-marker'),pips=all('.showcase-pip');
  const gs = window.gsap;
  let index=0,rotationGoal=0,rotation=0,timer=null,userPaused=media.matches,hovering=false,focused=false,interacting=false,visible=true,token=0,drag=null,blockClickUntil=0;
  let idleDelay=4500;
  const modulo = value => ((value%5)+5)%5;
  function sync(angle){rotation=angle;markers.forEach(marker=>{marker.querySelector('.marker-content').style.transform=`rotate(${-angle}deg)`;});rotor.dataset.rotation=String(Math.round(angle*100)/100);}
  function stop(){if(timer)clearTimeout(timer);timer=null;root.classList.remove('is-playing');}
  function canPlay(){return !userPaused&&!media.matches&&!hovering&&!focused&&!interacting&&visible&&!document.hidden&&!document.querySelector('dialog[open]');}
  function playbackLabel(){const paused=userPaused||media.matches;find('#showcase-play').setAttribute('aria-pressed',String(paused));find('#showcase-play').setAttribute('aria-label',paused?'Play automatic product rotation':'Pause automatic product rotation');find('#showcase-play').textContent=paused?'▶':'Ⅱ';find('#showcase-play').disabled=media.matches;find('#showcase-motion-status').textContent=media.matches?'Reduced motion · manual exploration':paused?'Autoplay paused':hovering||focused||interacting?'Paused while you explore':'Auto · 4.5 seconds';}
  function schedule(delay=4500){stop();idleDelay=delay;playbackLabel();if(!canPlay())return;root.style.setProperty('--play-duration',`${delay}ms`);root.classList.add('is-playing');timer=setTimeout(()=>{timer=null;go(modulo(index+1),{delta:1,source:'auto'});},delay);}
  function intent(){stop();playbackLabel();}
  function resume(){schedule(4000);}
  function updateContent(){const p=entries[index];find('#showcase-title').innerHTML=p.title;find('#showcase-badge').textContent=p.badge;find('#showcase-description').textContent=p.description;find('#showcase-highlights').replaceChildren(...p.points.map(text=>{const item=document.createElement('li');item.textContent=text;return item;}));find('#showcase-price').textContent=p.price;find('#showcase-terms').textContent=p.terms;find('#showcase-enquire').dataset.enquire=p.key;find('#showcase-enquire .cta-label').textContent=p.cta;find('#showcase-details').dataset.product=p.key;find('#showcase-image').src=p.image;find('#showcase-image').alt=p.alt;find('#showcase-caption').textContent=p.caption;find('#showcase-count').textContent=String(index+1).padStart(2,'0')+' / 05';root.dataset.activeProduct=p.key;markers.forEach((m,i)=>{m.classList.toggle('is-active',i===index);m.setAttribute('aria-pressed',String(i===index));});pips.forEach((p,i)=>{p.classList.toggle('is-active',i===index);p.setAttribute('aria-pressed',String(i===index));});}
  function go(next,options={}){const previous=index;let diff=next-previous;if(options.delta!==undefined)diff=options.delta;else{if(diff>2)diff-=5;if(diff< -2)diff+=5;}index=modulo(next);rotationGoal=options.angle!==undefined?options.angle:rotationGoal-diff*72;const myToken=++token;find('#showcase-enquire').dataset.enquire=entries[index].key;find('#showcase-details').dataset.product=entries[index].key;stop();
    if(gs&&!media.matches){gs.killTweensOf([rotor,copy,art]);gs.to(rotor,{rotation:rotationGoal,duration:options.duration??.95,ease:'power3.out',overwrite:true,onUpdate:()=>sync(Number(gs.getProperty(rotor,'rotation'))),onComplete:()=>{sync(rotationGoal);if(drag)drag.update();}});gs.to(copy,{opacity:0,y:-9,duration:.17,onComplete:()=>{if(myToken!==token)return;updateContent();gs.fromTo(copy,{opacity:0,y:15},{opacity:1,y:0,duration:.5,ease:'power2.out'});}});gs.to(art,{opacity:0,x:-65,scale:.84,duration:.23,onComplete:()=>{if(myToken!==token)return;updateContent();gs.fromTo(art,{opacity:0,x:75,y:9,scale:.88},{opacity:1,x:0,y:0,scale:1,duration:.86,ease:'elastic.out(1,0.85)',clearProps:'transform'});}});
    }else{rotor.style.transform=`rotate(${rotationGoal}deg)`;sync(rotationGoal);updateContent();}
    if(options.source!=='auto')find('#showcase-announcement').textContent=entries[index].plain+'. '+entries[index].badge;
    schedule(options.source==='auto'?4500:4000);
  }
  all('[data-showcase-go]').forEach(button=>button.addEventListener('click',()=>{if(performance.now()<blockClickUntil)return;go(Number(button.dataset.showcaseGo),{source:'pip'});}));
  find('#showcase-prev').addEventListener('click',()=>go(modulo(index-1),{delta:-1,source:'arrow'}));find('#showcase-next').addEventListener('click',()=>go(modulo(index+1),{delta:1,source:'arrow'}));
  find('#showcase-play').addEventListener('click',()=>{userPaused=!userPaused;schedule(4500);});
  root.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'&&finePointer.matches){hovering=true;intent();}});root.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse'){hovering=false;resume();}});
  root.addEventListener('focusin',event=>{focused=event.target.matches(':focus-visible');if(focused)intent();});root.addEventListener('focusout',()=>{setTimeout(()=>{focused=root.contains(document.activeElement)&&document.activeElement.matches(':focus-visible');if(!focused)resume();},0);});
  root.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea'))return;if(e.key==='ArrowRight'){e.preventDefault();go(modulo(index+1),{delta:1,source:'keyboard'});}else if(e.key==='ArrowLeft'){e.preventDefault();go(modulo(index-1),{delta:-1,source:'keyboard'});}else if(e.key==='Home'){e.preventDefault();go(0,{source:'keyboard'});}else if(e.key==='End'){e.preventDefault();go(4,{source:'keyboard'});}});
  document.addEventListener('close',resume,true);
  document.addEventListener('visibilitychange',()=>document.hidden?stop():schedule(4500));
  if('IntersectionObserver'in window)new IntersectionObserver(([entry])=>{visible=entry.isIntersecting;if(visible)schedule(4500);else stop();},{threshold:.2}).observe(root);
  media.addEventListener('change',()=>{userPaused=media.matches;if(gs)gs.killTweensOf([rotor,copy,art]);rotor.style.transform=`rotate(${rotationGoal}deg)`;copy.style.opacity='1';copy.style.transform='';art.style.opacity='1';art.style.transform='';sync(rotationGoal);updateContent();schedule(4500);});
  const now=()=>performance.now();
  function settle(angle,velocity,source){const projected=angle+Math.max(-.7,Math.min(.7,velocity))*130;const target=Math.round(projected/72)*72;root.classList.remove('is-dragging');interacting=false;blockClickUntil=now()+260;go(modulo(-Math.round(target/72)),{angle:target,duration:Math.max(.35,Math.min(.85,.45+Math.abs(target-angle)/210)),source});}
  if(gs&&window.Draggable&&finePointer.matches&&window.innerWidth>780){gs.registerPlugin(window.Draggable);let lastAngle=0,lastTime=0,velocity=0;drag=window.Draggable.create(rotor,{type:'rotation',trigger:surface,dragClickables:true,minimumMovement:7,cursor:'grab',activeCursor:'grabbing',onPress(){interacting=true;intent();gs.killTweensOf(rotor);lastAngle=Number(gs.getProperty(rotor,'rotation'));lastTime=now();velocity=0;},onDragStart(){root.classList.add('is-dragging');},onDrag(){const t=now();const elapsed=t-lastTime;if(elapsed>0)velocity=.5*velocity+.5*(this.rotation-lastAngle)/elapsed;lastAngle=this.rotation;lastTime=t;sync(this.rotation);},onRelease(){if(!this.isDragging){interacting=false;resume();}},onDragEnd(){if(now()-lastTime>130)velocity=0;settle(this.rotation,velocity,'drag');}})[0];root.dataset.dragEngine='gsap-draggable';}
  if(!drag)root.dataset.dragEngine='native-swipe';
  // A horizontal touch gesture preserves native vertical scrolling. Also serves as the CDN-free fallback.
  let gesture=null;
  surface.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&drag)return;if(e.button&&e.button!==0)return;interacting=true;intent();if(gs)gs.killTweensOf(rotor);const rect=surface.getBoundingClientRect();gesture={id:e.pointerId,startX:e.clientX,startY:e.clientY,x:e.clientX,lastX:e.clientX,lastTime:now(),velocity:0,startAngle:rotation,started:false,cx:rect.left+rect.width/2,cy:rect.top+rect.height/2};});
  surface.addEventListener('pointermove',e=>{if(!gesture||gesture.id!==e.pointerId)return;const g=gesture,dx=e.clientX-g.startX,dy=e.clientY-g.startY;if(!g.started){if(Math.abs(dy)>Math.abs(dx)&&Math.abs(dy)>10)return;if(Math.abs(dx)<9)return;g.started=true;surface.setPointerCapture(e.pointerId);root.classList.add('is-dragging');}if(e.cancelable)e.preventDefault();const t=now();const elapsed=t-g.lastTime;if(elapsed>0)g.velocity=.5*g.velocity+.5*(e.clientX-g.lastX)/elapsed;g.lastX=e.clientX;g.lastTime=t;g.x=e.clientX;const angle=g.startAngle+dx*.4;if(gs)gs.set(rotor,{rotation:angle});else rotor.style.transform=`rotate(${angle}deg)`;sync(angle);});
  function finish(e,cancelled=false){if(!gesture||gesture.id!==e.pointerId)return;const g=gesture;gesture=null;interacting=false;if(g.started){if(surface.hasPointerCapture(e.pointerId))surface.releasePointerCapture(e.pointerId);let velocity=now()-g.lastTime>140?0:g.velocity*.4;let angle=rotation;if(!cancelled&&Math.abs(g.x-g.startX)>35&&Math.round((angle+velocity*130)/72)===Math.round(g.startAngle/72)){angle=g.startAngle+(g.x<g.startX?-42:42);}settle(angle,cancelled?0:velocity,'swipe');}else resume();}
  surface.addEventListener('pointerup',e=>finish(e));surface.addEventListener('pointercancel',e=>finish(e,true));
  // Prevent a drag ending over a marker from being interpreted as a product click.
  surface.addEventListener('click',e=>{if(now()<blockClickUntil){e.preventDefault();e.stopPropagation();}},true);
  entries.forEach(p=>{const image=new Image();image.src=p.image;});
  updateContent();sync(0);schedule(4500);
})();
